                contributions = {}

                for (nr, nc), val in nonzero_positions:
                    dist = max(abs(z_r - nr), abs(z_c - nc))
                    if dist <= 2:
                        weight = 1 / (dist + 1)  # Weight decreases with distance

                        key = round(val * 10) // 10  # Round to avoid too many unique keys
                        if key not in contributions:
                            contributions[key] = {"sum": 0, "count": 0}
                        contributions[key]["sum"] += weight * val
                        contributions[key]["count"] += weight

                # If any contribution, round and assign
                if contributions:
                    final_val = 0
                    for key, data in contributions.items():
                        avg_val = data["sum"] / data["count"]
                        final_val += avg_val

                    result[z_r, z_c] = int(round(final_val))

